/**
 * Repoints every issue carrying `sourceLabelId` onto `targetLabelId`, then
 * removes the source label. Runs inside one transaction so a crash mid-merge
 * can't leave issues detached from both labels.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  const db = getDb();

  return db.transaction((tx) => {
    const affected = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();

    const targetHolders = new Set(
      tx
        .select({ issueId: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, targetLabelId),
          ),
        )
        .all()
        .map((row) => row.issueId),
    );

    const toInsert = affected
      .map((row) => row.issueId)
      .filter((issueId) => !targetHolders.has(issueId));

    if (toInsert.length > 0) {
      tx.insert(issueLabels)
        .values(
          toInsert.map((issueId) => ({
            orgId,
            issueId,
            labelId: targetLabelId,
          })),
        )
        .run();
    }

    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return affected.length;
  });
}

/** Batched lookup keyed by issue id, so list views avoid an N+1. */

