/**
 * Folds `sourceLabelId` into `targetLabelId`: every issue carrying the
 * source ends up carrying the target instead, and the source label is
 * removed. Same blast radius as `deleteLabel`, so it takes the same
 * permission.
 */
export async function mergeLabels(
  actor: Actor,
  input: MergeLabelsInput,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:archive", orgResource(input.orgId));

  if (input.sourceLabelId === input.targetLabelId) {
    throw new Error("sourceLabelId and targetLabelId must differ");
  }

  const [source, target] = await Promise.all([
    labelRepo.getLabel(input.orgId, input.sourceLabelId),
    labelRepo.getLabel(input.orgId, input.targetLabelId),
  ]);
  if (!source) throw new NotFoundError("Label", input.sourceLabelId);
  if (!target) throw new NotFoundError("Label", input.targetLabelId);

  const issuesRelabelled = await labelRepo.mergeLabels(
    input.orgId,
    input.sourceLabelId,
    input.targetLabelId,
  );

  return { label: target, issuesRelabelled };
}

